class LRUCache:
    """A class that implements an LRU (Least Recently Used) Cache using a
    hashmap for O(1) access time and a list to maintain the order of keys. 
    The most recently used key is moved to the end of the list.
    """

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.keys = []

    def get(self, key: int) -> int:
        if key in self.cache:
            # Move the key to the end to mark it as recently used
            self.keys.remove(key)
            self.keys.append(key)
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            # Update the value and mark as recently used
            self.cache[key] = value
            self.keys.remove(key)
            self.keys.append(key)
        else:
            if len(self.cache) >= self.capacity:
                # Remove the least recently used item
                lru_key = self.keys.pop(0)
                del self.cache[lru_key]
            # Add new item
            self.cache[key] = value
            self.keys.append(key)

class DoublyLinkedList:
    """A helper class to maintain the order of elements in the LRU Cache using a simple
    doubly linked list implementation without dummy nodes.
    """

    class Node:
        def __init__(self, key, value):
            self.key = key
            self.value = value
            self.prev = None
            self.next = None

    def __init__(self):
        self.head = None
        self.tail = None

    def append(self, node):
        if not self.head:
            self.head = node
            self.tail = node
        else:
            self.tail.next = node
            node.prev = self.tail
            self.tail = node

    def remove(self, node):
        if node.prev:
            node.prev.next = node.next
        if node.next:
            node.next.prev = node.prev
        if node == self.head:
            self.head = node.next
        if node == self.tail:
            self.tail = node.prev

class LRUCache:
    """A class that implements an LRU (Least Recently Used) Cache using a hashmap for 
    O(1) access time and a custom doubly linked list to maintain the order of usage.
    """

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.order = DoublyLinkedList()

    def get(self, key: int) -> int:
        if key in self.cache:
            node = self.cache[key]
            self.order.remove(node)
            self.order.append(node)
            return node.value
        return -1

    def put(self, key: int, value: int) -> None:
        if key in self.cache:
            self.order.remove(self.cache[key])
        elif len(self.cache) >= self.capacity:
            lru_node = self.order.head
            self.order.remove(lru_node)
            del self.cache[lru_node.key]

        new_node = DoublyLinkedList.Node(key, value)
        self.order.append(new_node)
        self.cache[key] = new_node
